#include <stdio.h>
#include <stdlib.h>

int main(int argc, char *argv[])
{
    /* No arguments after program name */
    if (argc < 2) {
        puts("NO_INPUT");
        return 0;
    }

    /* Parse x (first argument) */
    char *endptr;
    long x = strtol(argv[1], &endptr, 10);
    if (*endptr != '\0') {
        puts("BAD_INPUT");
        return 0;
    }
    if (x > 10) {
        puts("OUT_OF_RANGE");
        return 0;
    }

    /* Remaining arguments are coefficients */
    int coeff_cnt = argc - 2;
    if (coeff_cnt == 0) {
        puts("EMPTY");
        return 0;
    }
    if (argc > 14) { // more than 12 coefficients
        puts("OUT_OF_RANGE");
        return 0;
    }

    long coeff[12];
    for (int i = 0; i < coeff_cnt; ++i) {
        long v = strtol(argv[2 + i], &endptr, 10);
        if (*endptr != '\0') {
            puts("BAD_INPUT");
            return 0;
        }
        if (v > 1000) { // only positive bound is checked in original
            puts("OUT_OF_RANGE");
            return 0;
        }
        coeff[i] = v;
    }

    /* Horner evaluation */
    long result = 0;
    for (int i = 0; i < coeff_cnt; ++i) {
        result = result * x + coeff[i];
    }

    printf("%lld\n", result);
    return 0;
}
